#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

spec fn is_odd(x: i32) -> bool {
    x % 2 != 0
}

fn find_first_odd(a: &[i32]) -> (found: bool, index: usize)
    ensures
        // If not found, all elements are even; index may be arbitrary
        !found ==> (forall|i: int| 0 <= i < a.len() ==> !is_odd(a[i])),
        // If found, index is valid, a[index] is odd, and everything before is even
        found ==> index < a.len()
               && is_odd(a[index])
               && (forall|i: int| 0 <= i < index ==> !is_odd(a[i]))
{
    let mut i: usize = 0;

    while i < a.len()
        invariant
            0 <= i <= a.len(),
            // Everything strictly before i is even (we haven't returned yet)
            forall|j: int| 0 <= j < i ==> !is_odd(a[j]),
        decreases a.len() - i
    {
        if a[i] % 2 != 0 {
            // Establish the postcondition for the found case
            assert(is_odd(a[i]));
            assert(i < a.len());
            assert(forall|j: int| 0 <= j < i ==> !is_odd(a[j]));
            return (true, i);
        }
        i += 1;
    }

    // Establish the postcondition for the not-found case
    assert(forall|j: int| 0 <= j < a.len() ==> !is_odd(a[j]));
    (false, 0)
}

} // verus!